CREATE FUNCTION public.pilot_accept_offer(_offer uuid,_approve boolean,_amount integer,_version timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d uuid;o public.provider_trip_offers;r jsonb;BEGIN PERFORM 1 FROM public.trip_network_settings WHERE id=true FOR SHARE;SELECT distribution_id INTO d FROM public.provider_trip_offers WHERE id=_offer;PERFORM 1 FROM public.trip_distributions WHERE id=d FOR UPDATE;SELECT * INTO o FROM public.provider_trip_offers WHERE id=_offer FOR UPDATE;
